-- Rewrite legacy collection variants as canonical variant keys.
-- Generated by dexter-ops/scripts/migrate_collection_variants.py.
--
-- Applied manually via the Supabase MCP `apply_migration` (see
-- tcgdexter-web/CLAUDE.md — there is no CI migration runner). Applied
-- 2026-08-10; apply_migration supplies its own transaction, so the BEGIN/COMMIT
-- this file was generated with are stripped below.
--
-- Reversible from public.user_card_collection_backup_20260810, taken
-- immediately before (2419 rows / 4413 qty, matching the post-migration
-- totals). Drop that table once the new keys have had a few days in the UI.
--
-- Rows are merged rather than replaced where two legacy strings collapse onto
-- the same canonical key, so the (user_id, set_id, number, variant) primary key
-- still holds and no quantity is lost.


-- `set_id`/`number` of '*' means the mapping holds for every card; specific
-- values mean it was resolved against that card's actual printings.
CREATE TEMP TABLE variant_remap (
  set_id      text NOT NULL,
  number      text NOT NULL,
  old_variant text NOT NULL,
  new_variant text NOT NULL
) ON COMMIT DROP;

