-- Per-card rows win over wildcards, so a card-specific resolution isn't
-- overridden by a generic one for the same legacy string.
CREATE TEMP VIEW remap_for_row AS
SELECT DISTINCT ON (c.user_id, c.set_id, c.number, c.variant)
       c.user_id, c.set_id, c.number, c.variant AS old_variant, r.new_variant
FROM public.user_card_collection c
JOIN variant_remap r
  ON r.old_variant = c.variant
 AND (r.set_id = '*' OR (r.set_id = c.set_id AND r.number = c.number))
ORDER BY c.user_id, c.set_id, c.number, c.variant, (r.set_id = '*');

-- 1. Fold rows whose target key already exists for that user into it.
WITH folded AS (
  DELETE FROM public.user_card_collection c
  USING remap_for_row r
  WHERE c.user_id = r.user_id AND c.set_id = r.set_id
    AND c.number = r.number AND c.variant = r.old_variant
    AND EXISTS (
      SELECT 1 FROM public.user_card_collection t
      WHERE t.user_id = c.user_id AND t.set_id = c.set_id
        AND t.number = c.number AND t.variant = r.new_variant
    )
  RETURNING c.user_id, c.set_id, c.number, r.new_variant, c.quantity
)
UPDATE public.user_card_collection t
SET quantity = t.quantity + f.quantity
FROM folded f
WHERE t.user_id = f.user_id AND t.set_id = f.set_id
  AND t.number = f.number AND t.variant = f.new_variant;

-- 2. Rename the rest in place.
UPDATE public.user_card_collection c
SET variant = r.new_variant
FROM remap_for_row r
WHERE c.user_id = r.user_id AND c.set_id = r.set_id
  AND c.number = r.number AND c.variant = r.old_variant;
